 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # A straight color-2 guide borders a small colored object; extend an 8-line
    # one cell beyond the object's far edge, parallel to the guide.
    guide_col = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
    guide_row = next((r for r in range(h) if all(grid[r][c] == 2 for c in range(w))), None)
    obj = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (2, 5, 8)]
    if guide_col is not None and obj:
        cols = [c for _, c in obj]
        if max(cols) < guide_col:
            line = min(cols) - 1
        elif min(cols) > guide_col:
            line = max(cols) + 1
        else:
            return out
        if 0 <= line < w:
            for r in range(h):
                out[r][line] = 8
    elif guide_row is not None and obj:
        rows = [r for r, _ in obj]
        if max(rows) < guide_row:
            line = min(rows) - 1
        elif min(rows) > guide_row:
            line = max(rows) + 1
        else:
            return out
        if 0 <= line < h:
            out[line] = [8] * w
    return out
